/** 9-slice inset in output pixels, ordered [top, right, bottom, left]. */
export type Slice = [number, number, number, number];

export type AssetCategory =
  | 'background'
  | 'banner'
  | 'bar'
  | 'button'
  | 'decor'
  | 'frame'
  | 'glyph'
  | 'icon'
  | 'panel'
  | 'silhouette'
  | 'slot';

export interface AssetRecord {
  /** Stable identifier, unique within its pack. */
  id: string;
  /** Owning pack / theme id. */
  pack: string;
  /** Human-readable label. */
  name: string;
  category: AssetCategory;
  /** Encoding of the shipped file. SVG glyphs are tintable through a CSS mask. */
  format: 'png' | 'webp' | 'svg';
  tags: string[];
  /** Path relative to the asset base, e.g. "stone-vine/panel-stone.png". */
  file: string;
  /** Small WebP preview, site gallery only. */
  thumb: string;
  width: number;
  height: number;
  /** 9-slice insets, or null when the art must keep its natural aspect ratio. */
  slice: Slice | null;
  bytes: number;
}

export interface PackRecord {
  id: string;
  name: string;
  /** A `theme` pack binds the semantic slots; every other kind is an art collection. */
  kind: 'frames' | 'icons' | 'theme';
  blurb: string;
  accent: string;
  count: number;
}

